const GRID_SIZE = 9;
const SUBGRID_SIZE = 3;

const shuffleArray = (array) => {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
};

export const emptyGrid = () => Array(GRID_SIZE).fill(null).map(() => Array(GRID_SIZE).fill(0));

export const deepCopyGrid = (grid) => JSON.parse(JSON.stringify(grid));

const isValidPlacement = (board, row, col, num) => {
    for (let i = 0; i < GRID_SIZE; i++) {
        if (board[row][i] === num || board[i][col] === num) return false;
    }
    const boxRow = Math.floor(row / SUBGRID_SIZE) * SUBGRID_SIZE;
    const boxCol = Math.floor(col / SUBGRID_SIZE) * SUBGRID_SIZE;
    for (let i = 0; i < SUBGRID_SIZE; i++) {
        for (let j = 0; j < SUBGRID_SIZE; j++) {
            if (board[boxRow + i][boxCol + j] === num) return false;
        }
    }
    return true;
};

const generateSolvedGrid = () => {
    const grid = emptyGrid();
    const nums = shuffleArray([1, 2, 3, 4, 5, 6, 7, 8, 9]);

    const solveWithBacktracking = (board) => {
        for (let row = 0; row < GRID_SIZE; row++) {
            for (let col = 0; col < GRID_SIZE; col++) {
                if (board[row][col] === 0) {
                    for (let num of nums) {
                        if (isValidPlacement(board, row, col, num)) {
                            board[row][col] = num;
                            if (solveWithBacktracking(board)) return true;
                            board[row][col] = 0;
                        }
                    }
                    return false;
                }
            }
        }
        return true;
    };
    solveWithBacktracking(grid);
    return grid;
};

export const generatePuzzle = (level) => {
    const solvedGrid = generateSolvedGrid();
    const puzzle = deepCopyGrid(solvedGrid);
    const clues = { easy: 40, medium: 30, hard: 25 }[level];
    const cellIndices = [];
    for (let row = 0; row < GRID_SIZE; row++) {
        for (let col = 0; col < GRID_SIZE; col++) {
            cellIndices.push({ row, col });
        }
    }
    shuffleArray(cellIndices);

    let removedClues = 0;
    for (let { row, col } of cellIndices) {
        if (removedClues >= GRID_SIZE * GRID_SIZE - clues) break;
        if (puzzle[row][col] !== 0) {
            puzzle[row][col] = 0;
            removedClues++;
        }
    }
    return { puzzle, solvedGrid };
};

export const updateDuplicates = (newGrid) => {
    const newHighlights = new Set();

    for (let i = 0; i < GRID_SIZE; i++) {
        const rowNums = new Map();
        const colNums = new Map();
        const subGridNums = new Map();
        const boxRow = Math.floor(i / SUBGRID_SIZE) * SUBGRID_SIZE;
        const boxCol = (i % SUBGRID_SIZE) * SUBGRID_SIZE;

        for (let j = 0; j < GRID_SIZE; j++) {
            const numRow = newGrid[i][j];
            if (numRow !== 0) {
                if (rowNums.has(numRow)) {
                    newHighlights.add(`${i}-${j}`);
                    newHighlights.add(`${i}-${rowNums.get(numRow)}`);
                } else {
                    rowNums.set(numRow, j);
                }
            }
            const numCol = newGrid[j][i];
            if (numCol !== 0) {
                if (colNums.has(numCol)) {
                    newHighlights.add(`${j}-${i}`);
                    newHighlights.add(`${colNums.get(numCol)}-${i}`);
                } else {
                    colNums.set(numCol, j);
                }
            }
            const subRow = boxRow + Math.floor(j / SUBGRID_SIZE);
            const subCol = boxCol + (j % SUBGRID_SIZE);
            const numSubGrid = newGrid[subRow][subCol];
            if (numSubGrid !== 0) {
                const subGridKey = `${subRow}-${subCol}`;
                if (subGridNums.has(numSubGrid)) {
                    newHighlights.add(subGridKey);
                    newHighlights.add(`${subGridNums.get(numSubGrid).row}-${subGridNums.get(numSubGrid).col}`);
                } else {
                    subGridNums.set(numSubGrid, { row: subRow, col: subCol });
                }
            }
        }
    }
    return newHighlights;
};