import React, { useState, useEffect } from 'react';
import Modal from 'react-modal';
import Slider from 'react-slick';
import 'slick-carousel/slick/slick.css';
import 'slick-carousel/slick/slick-theme.css';
import '../assets/css/mlProjects.css';

import heatmap from '../projects/ccfd/heatmap.png';
import table from '../projects/ccfd/table.png';
import top10 from '../projects/ccfd/top10.png';
import capstone from '../projects/ccfd/CS497_CP10_CapstoneReport_DhrushalGada.pdf';
import bigram from '../projects/realvsfake/bi-gram.png';
import wordCloud from '../projects/realvsfake/cleanedWordCloud.png';
import importance from '../projects/realvsfake/featureImportance.png';
import report from '../projects/realvsfake/report.png';
import freq from '../projects/planeCrashes/freqWords.png';
import planeCloud from '../projects/planeCrashes/wordCloud.png';
import quingram from '../projects/planeCrashes/quingram.png';

const SLIDER_SETTINGS = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
};

const projects = [
    {
        cardName: 'Credit Card Fraud Detection',
        description:'In this project, I developed fraud detection models using PCA-anonymized data to ensure privacy. I implemented machine learning techniques like aggressive under-sampling and SMOTE, with under-sampling proving more effective for reducing bias. By combining these with hybrid modeling, I achieved high precision and recall in detecting fraud. This project showcases the power of machine learning for secure digital transactions while preserving privacy. Explore the full analysis for innovative insights into fraud detection.',
        previewIcons: [heatmap, table, top10],
        fullImages: [
        { src: heatmap, description: 'Heatmap of processed data' },
        { src: table, description: 'Table of minority class and macro metrics' },
        { src: top10, description: 'Top 10 influencing features highlighted via RFC' },
        ],
        modelsDev: [
            'Support Vector Machine',
            'Random Forest Classifier',
            'Feed-Forward Neural Network',
            'Convolutional Neural Network',
            'Hybrid Models',
        ],
        document: capstone,
        data:'',
    },
    {
        cardName: 'Real Vs Fake News Classification',
        description: 'From preprocessing to model training, I cleaned and prepared the text data by lowercasing, removing stopwords, and tokenizing, then transformed it into numerical features using TF-IDF. I trained a Random Forest model, fine-tuned its hyperparameters with Grid Search, and achieved near-perfect performance: 99.76% accuracy, with only 15 false positives and 6 false negatives. This shows my model is highly effective at distinguishing between fake and real news.',
        previewIcons: [wordCloud, bigram, importance, report],
        fullImages: [
            { src: wordCloud, description: 'Fake News Detection - Image 1' },
            { src: bigram, description: 'Fake News Detection - Image 2' },
            { src: importance, description: 'Fake News Detection - Image 2' },
            { src: report, description: 'Fake News Detection - Image 2' },
        ],
        modelsDev: ['Support Vector Machine', 'Random Forest Classifier', 'Feed-Forward Neural Network'],
        document: '',
        data:'https://www.kaggle.com/datasets/clmentbisaillon/fake-and-real-news-dataset/data',
    },
    {
        cardName: 'Plane Crashes',
        description: '',
        previewIcons: [planeCloud, quingram, freq],
        fullImages: [],
        modelsDev: [],
        document: '',
        data: '',
    },
];

const ProjectCard = ({ project, index, openModal, toggleCard, openCardIndex, setIsDocOpen}) => {
    const isOpen = openCardIndex === index;
    return (
        <div className={`card `} onClick={() => toggleCard(index)}>
            <div className="card-icons">
                {project.previewIcons.map((icon, idx) => (
                <img key={idx} src={icon} alt="preview" className="preview-icon" onClick={(e) => { e.stopPropagation(); openModal(project.fullImages, idx); }}/>
                ))}
            </div>
            <div className="card-title">
                {project.cardName}
                <span className={`ml-5 arrow ${isOpen ? 'up' : 'down'}`}>{isOpen ? '↑' : '↓'}</span>
            </div>
            {isOpen && (
                <div className="hidden-content">
                    <div className="card-description">{project.description}</div>
                    <div className="model-list">
                        <p className="font-bold">Models developed</p>
                        <ul>
                            {project.modelsDev.map((model, idx) => (
                                <li key={idx}>{model}</li>
                            ))}
                        </ul>
                    </div>
                    {project.document && (
                        <div className="mt-2">
                            <a href="#" onClick={(e) => { e.preventDefault(); setIsDocOpen(true); }} className="text-blue-500 underline">
                                My Research
                            </a>
                        </div>
                    )}
                </div>
            )}
        </div>
    );
};

const ImageModal = ({ isOpen, onClose, images, initialIndex }) => {
    return (
        <Modal isOpen={isOpen} onRequestClose={onClose} contentLabel="Image Modal" className="modal-content" overlayClassName="modal-overlay" >
            {images.length > 0 && (
                <Slider className="modal-slider" initialSlide={initialIndex} {...SLIDER_SETTINGS}>
                    {images.map((image, idx) => (
                        <div className="content" key={idx}>
                            <img className="imgs" src={image.src} alt={image.description} />
                            <div className="image-description">{image.description}</div>
                        </div>
                    ))}
                </Slider>
            )}
            <button className="close-button" onClick={onClose}>X</button>
        </Modal>
    );
};

const MLProjects = ({darkMode}) => {
    const [modalState, setModalState] = useState({ isOpen: false, images: [], initialIndex: 0 });
    const [openCardIndex, setOpenCardIndex] = useState(null);
    const [isDocOpen, setIsDocOpen] = useState(false);

    const openModal = (images, index) => { setModalState({ isOpen: true, images, initialIndex: index }); };
    const closeModal = () => { setModalState({ isOpen: false, images: [], initialIndex: 0 }); };
    const toggleCard = (index) => { setOpenCardIndex(openCardIndex === index ? null : index); };

    return (
        <div className="grid-container">
            {projects.map((project, index) => (
                <ProjectCard key={index} project={project} index={index} openModal={openModal} darkMode={darkMode} toggleCard={toggleCard} openCardIndex={openCardIndex} setIsDocOpen={setIsDocOpen}/>
            ))}
            {isDocOpen && (
                <div className="fixed inset-0 flex justify-center items-center z-50">
                    <button onClick={() => setIsDocOpen(false)} className="close-button right-2">&times;</button>
                    <iframe src={capstone} title="resume" className="res-modal"></iframe>
                </div>
            )}
            <ImageModal isOpen={modalState.isOpen} onClose={closeModal} images={modalState.images} initialIndex={modalState.initialIndex}/>
        </div>
    );
};

export default MLProjects;