import { useState, useRef } from "react";
import CodeProjects from "../components/CodeProjects";
import MLProjects from "../components/MLProjects";
import DAProjects from "../components/DAProjects";
import "../assets/css/projects.css";

const Projects = (darkMode) => {
    const [activeTab, setActiveTab] = useState("code");
    const [carouselIndex, setCarouselIndex] = useState(0);
    const [isDragging, setIsDragging] = useState(false);
    const [startX, setStartX] = useState(0);
    const [currentX, setCurrentX] = useState(0);
    const [flipDirection, setFlipDirection] = useState(null); // Track flip direction
    const carouselRef = useRef(null);
    const tabOrder = ["code", "ml", "da"];
    const numTabs = tabOrder.length;

    const renderComponent = () => {
        switch (activeTab) {
            case "code":
                return <CodeProjects />;
            case "ml":
                return <MLProjects darkMode={darkMode} />;
            case "da":
                return <DAProjects />;
            // case "lc":
            //     return <DAProjects />;
            default:
                return <CodeProjects darkMode={darkMode} />;
        }
    };

    const handleCarousel = (direction) => {
        let newIndex = carouselIndex + direction;
    
        // Wrap around the carousel
        if (newIndex < 0) newIndex = numTabs - 1;
        if (newIndex >= numTabs) newIndex = 0;
    
        // Set flip direction
        setFlipDirection(direction === -1 ? "right" : "left");
    
        // Wait for the flip transition to complete before updating the tab
        setTimeout(() => {
            setCarouselIndex(newIndex);
            setActiveTab(tabOrder[newIndex]);
            setFlipDirection(null); // Reset flip direction after transition
        }, 300); // Match the duration of the CSS transition
    };
    

    const handleDragStart = (e) => {
        setIsDragging(true);
        setStartX(e.touches ? e.touches[0].clientX : e.clientX);
        setCurrentX(startX);
    };

    const handleDragMove = (e) => {
        if (!isDragging) return;
        const x = e.touches ? e.touches[0].clientX : e.clientX;
        setCurrentX(x);
    };

    const handleDragEnd = () => {
        if (!isDragging) return;
        setIsDragging(false);
        const deltaX = currentX - startX;
        const threshold = 50;
        if (Math.abs(deltaX) > threshold) {
            if (deltaX > 0) {
                handleCarousel(-1); // Drag right to go left
            } else {
                handleCarousel(1); // Drag left to go right
            }
        }
    };

    return (
        <div className="projects-container">
            <br />
            <p className="text-3xl lg:text-5xl md:text-4xl sm:text-4xl font-bold mt-12 mb-5"> Projects </p>
            
            <div className="carousel-container"
                ref={carouselRef}
                onMouseDown={handleDragStart}
                onMouseMove={handleDragMove}
                onMouseUp={handleDragEnd}
                onMouseLeave={handleDragEnd}
                onTouchStart={handleDragStart}
                onTouchMove={handleDragMove}
                onTouchEnd={handleDragEnd}>
                <button className="carousel-nav left-0" onClick={() => handleCarousel(-1)}>&#60;</button>

                <div className="carousel-tabs"
                    style={{ transform: `rotateY(${carouselIndex * -120}deg)`, transition: isDragging ? "none" : "transform 0.9s ease-in-out",}}>
                    {tabOrder.map((tab, index) => (
                        <div key={tab} className="carousel-item " 
                            style={{transform: `rotateY(${index * 120}deg) translateZ(250px)`,}}>
                            <p className={` text-xl lg:text-3xl md:text-2xl sm:text-2xl tab-item ${activeTab === tab ? "active" : ""}`} 
                                onClick={() => { setActiveTab(tab); setCarouselIndex(index);}}>
                                {tab === "code" && "Code"}
                                {tab === "ml" && "Machine Learning"}
                                {tab === "da" && "Data Analysis"}
                                {/* {tab === "lc" && "Leet Code"} */}
                            </p>
                        </div>
                    ))}
                </div>
                <button className="carousel-nav right-0" onClick={() => handleCarousel(1)}> &#62; </button>
            </div>

            <div className={`content-display ${flipDirection === "left" ? "rotate-left" : flipDirection === "right" ? "rotate-right" : ""}`}>
    {renderComponent()}
</div>
        </div>
    );
};

export default Projects;